&lt;p&gt;&lt;span style=&quot;font-weight: bold;&quot;&gt;&lt;span style=&quot;color: #0075db; font-size: 16px;&quot;&gt;Preferred Qualifications&lt;/span&gt;&lt;/span&gt;&lt;span style=&quot;color: #0075db; font-size: 16px;&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span style=&quot;font-family: Inter, sans-serif;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Experience in CI/CD tooling: Azure DevOps/GitHub Actions, Octopus Deploy&lt;/span&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span style=&quot;font-family: Inter, sans-serif;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Relevant certifications in cloud platforms (e.g., Microsoft Certified: Azure Solutions Architect) and DevOps practices (e.g., Certified Kubernetes Administrator) are a plus&lt;/span&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
