&lt;li&gt;&lt;span style=&quot;font-family: Inter, sans-serif;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Bachelor&#39;s degree in Computer Science, Information Technology, or similar&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span style=&quot;font-family: Inter, sans-serif;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;You have held a Technical Lead (or similar role) for at least 2 years&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
